import{_ as c,C as o,o as a,c as l,a0 as i,E as r,w as t,b as d,a1 as h,j as u}from"./chunks/framework.C5ukcOJf.js";const C=JSON.parse('{"title":"Authorization Code Flow","description":"","frontmatter":{"prev":{"text":"OAuth2","link":"/docs/concepts/oauth2"},"next":{"text":"Sessions","link":"/docs/concepts/sessions"}},"headers":[],"relativePath":"docs/references/authorization_code_flow.md","filePath":"docs/references/authorization_code_flow.md"}'),p={name:"docs/references/authorization_code_flow.md"};function f(g,e,v,k,_,m){const n=o("Mermaid"),s=o("ClientOnly");return a(),l("div",null,[e[1]||(e[1]=i('<h1 id="authorization-code-flow" tabindex="-1">Authorization Code Flow <a class="header-anchor" href="#authorization-code-flow" aria-label="Permalink to &quot;Authorization Code Flow&quot;">​</a></h1><p>The Authorization Code flow is the most widely recommended OAuth2 <a href="/okta-client-javascript/docs/concepts/oauth2#flows-grant-types">grant type</a> for any <a href="/okta-client-javascript/docs/concepts/oauth2#actors">client</a> that can direct a user&#39;s browser to an <a href="/okta-client-javascript/docs/concepts/oauth2#actors">authorization server</a> and receive a redirect back — single-page apps, native/mobile apps, and traditional server-rendered web apps.</p><p>Rather than returning tokens directly to the browser (as the now-deprecated Implicit flow did), the client first receives a short-lived, single-use <code>code</code>. That code is then exchanged for tokens over a separate back-channel request. This extra hop keeps tokens out of the browser history/URL and gives the authorization server a chance to bind the exchange to the client that started it.</p><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>Public clients (SPAs, native/mobile apps) can&#39;t safely hold a <code>client_secret</code>, since anything shipped to a device or browser can be extracted. <a href="/okta-client-javascript/docs/concepts/oauth2#common-terms">PKCE</a> closes this gap by having the client prove, at token-exchange time, that it&#39;s the same party that started the flow — without ever needing a static secret. It&#39;s on by default for every <code>AuthorizationCodeFlow</code> in this SDK.</p></div><h2 id="participants" tabindex="-1">Participants <a class="header-anchor" href="#participants" aria-label="Permalink to &quot;Participants&quot;">​</a></h2><ul><li><strong><a href="/okta-client-javascript/docs/concepts/oauth2#actors">Resource Owner</a>:</strong> the user completing sign-in</li><li><strong><a href="/okta-client-javascript/docs/concepts/oauth2#actors">Client</a>:</strong> your application</li><li><strong><a href="/okta-client-javascript/docs/concepts/oauth2#actors">Authorization Server</a>:</strong> authenticates the user and issues tokens</li><li><strong><a href="/okta-client-javascript/docs/concepts/oauth2#actors">Resource Server</a>:</strong> the API the client ultimately wants to call</li></ul><h2 id="how-it-works" tabindex="-1">How It Works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How It Works&quot;">​</a></h2>',7)),r(s,null,{default:t(()=>[(a(),d(h,null,{default:t(()=>[r(n,{id:"mermaid-42",class:"mermaid",graph:"sequenceDiagram%0A%20%20%20%20participant%20User%20as%20User%20(Browser)%0A%20%20%20%20participant%20Client%0A%20%20%20%20participant%20AS%20as%20Authorization%20Server%0A%20%20%20%20participant%20RS%20as%20Resource%20Server%0A%0A%20%20%20%20Client-%3E%3EClient%3A%20Generate%20state%2C%20nonce%2C%20code_verifier%2Fcode_challenge%0A%20%20%20%20Client-%3E%3EUser%3A%20Redirect%20to%20%2Fauthorize%20(client_id%2C%20redirect_uri%2C%20scope%2C%20state%2C%20code_challenge)%0A%20%20%20%20User-%3E%3EAS%3A%20GET%20%2Fauthorize%0A%20%20%20%20AS-%3E%3EUser%3A%20Prompt%20for%20authentication%20%2B%20consent%0A%20%20%20%20User-%3E%3EAS%3A%20Submit%20credentials%2C%20approve%20access%0A%20%20%20%20AS-%3E%3EUser%3A%20Redirect%20to%20redirect_uri%20(with%20code%2C%20state)%0A%20%20%20%20User-%3E%3EClient%3A%20Client%20parses%20code%20%2B%20state%20from%20url%20(redirect_uri)%0A%20%20%20%20Client-%3E%3EClient%3A%20Verify%20state%20matches%20original%20request%0A%20%20%20%20Client-%3E%3EAS%3A%20POST%20%2Ftoken%20(code%2C%20code_verifier%2C%20redirect_uri%2C%20client_id)%0A%20%20%20%20AS-%3E%3EAS%3A%20Validate%20code%2C%20PKCE%20verifier%2C%20client%0A%20%20%20%20AS-%3E%3EClient%3A%20access_token%20(%2B%20id_token%2C%20refresh_token)%0A%20%20%20%20Client-%3E%3ERS%3A%20Request%20with%20Authorization%3A%20Bearer%20access_token%0A%20%20%20%20RS-%3E%3EClient%3A%20Protected%20resource%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[u("div",{class:"mermaid mermaid--loading","aria-busy":"true","aria-label":"Loading diagram"},null,-1)])]),_:1}))]),_:1}),e[2]||(e[2]=i('<ol><li>The client generates a <code>state</code> value (and, for OIDC, a <code>nonce</code>), along with a PKCE <code>code_verifier</code> and its derived <code>code_challenge</code>.</li><li>The client redirects the user&#39;s browser to the authorization server&#39;s <code>/authorize</code> endpoint, including <code>client_id</code>, <code>redirect_uri</code>, <code>scope</code>, <code>state</code>, and <code>code_challenge</code>.</li><li>The user authenticates with the authorization server and approves the request (if a consent screen is required).</li><li>The authorization server redirects the browser back to the client&#39;s <code>redirect_uri</code> with an authorization <code>code</code> and the original <code>state</code>.</li><li>The client verifies the returned <code>state</code> matches what it sent in step 1, protecting against CSRF.</li><li>The client exchanges the <code>code</code> — along with the original PKCE <code>code_verifier</code> — for tokens via a <code>POST</code> to the authorization server&#39;s <code>/token</code> endpoint.</li><li>The authorization server validates the <code>client_id</code>, <code>code</code>, and PKCE <code>code_verifier</code>, then returns an access token (plus an ID token and/or refresh token, depending on the requested scopes).</li><li>The client uses the access token to call the resource server on the user&#39;s behalf.</li></ol><h2 id="security-considerations" tabindex="-1">Security Considerations <a class="header-anchor" href="#security-considerations" aria-label="Permalink to &quot;Security Considerations&quot;">​</a></h2><ul><li><strong><code>state</code></strong> must be unique per authorization request and verified on redirect — it&#39;s what stops an attacker from tricking a user into completing someone else&#39;s flow.</li><li><strong><code>nonce</code></strong> (OIDC) is echoed back inside the ID token itself, protecting against replay of a previously issued token.</li><li><strong>PKCE</strong> protects the <code>code</code>-for-token exchange even if the authorization <code>code</code> is intercepted in transit, since only the party holding the original <code>code_verifier</code> can redeem it.</li><li><strong>DPoP</strong> goes a step further than PKCE by binding the <em>issued tokens</em> to a private key generated on the client. Every request made with a DPoP-bound token — the token exchange itself, and every subsequent call to a resource server — must be accompanied by a fresh proof signed with that key. A leaked or intercepted access/refresh token is useless to an attacker without the private key, which never leaves the client.</li><li>Because everything relies on the client still having its original <code>state</code>/<code>code_verifier</code>, that data has to survive the full round trip to the authorization server and back — including a full-page redirect on the web.</li></ul><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>All of these security controls are enabled by default within the Okta Client JavaScript ecosystem with the exception of <strong>DPoP</strong>, which is easily <a href="/okta-client-javascript/api/auth-foundation/OAuth2/namespaces/OAuth2Client/classes/Configuration#dpop">configurable</a></p></div><h2 id="see-also" tabindex="-1">See Also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See Also&quot;">​</a></h2><ul><li>Okta Documentation: <a href="https://developer.okta.com/docs/concepts/oauth-openid/#authorization-code-flow-with-pkce-flow" target="_blank" rel="noreferrer">Concepts</a> · <a href="https://developer.okta.com/docs/guides/implement-grant-type/authcode/main/#authorization-code-flow" target="_blank" rel="noreferrer">Implementation Guide</a></li><li><a href="https://oauth.net/2/grant-types/authorization-code" target="_blank" rel="noreferrer">oauth.net: Authorization Code Grant Type</a></li><li><a href="https://datatracker.ietf.org/doc/html/rfc6749#section-1.3.1" target="_blank" rel="noreferrer">RFC 6749, §1.3.1</a></li></ul>',6))])}const b=c(p,[["render",f]]);export{C as __pageData,b as default};
